/**
 * Changed-card integration check (Study Mode gate 1; in-progress-tasks "Changed-card verification sequence"): a studied
 * card whose own passage changes is regenerated by "Update from new content", and its study history follows it, marked
 * out of date. No AI and no network: a scripted mock distiller answers every call (as `notesStudy.local.spec.ts`).
 *
 * Six steps: mark a card Weak → change the source text behind it → Update from new content → the intended card
 * regenerates with no unrelated-card conflict → its history survives, marked "Source changed since you studied this",
 * and no other card picks it up → still so after a reload.
 *
 * Fix A (canvas-notes-39, `src/ai/reconcile/update.ts`) regenerates edited sections with the labelled distil prompt, but
 * only while the note model is distil, which resets on reload: so `setNoteModel("distil")` runs before the update.
 * Fix B (citation-lineage matching) isn't built yet; when it is, this spec runs once with it off and once with it on.
 */
import { expect, test, type Page, type Route } from "@playwright/test";
import type { AIRequest } from "../../src/ai/types";
import { distiller, type DistillerOptions } from "../../src/ai/fidelity/__fixtures__/knowledge/mockDistiller";
import { action, openAISettings, openApp, openAskAI, waitForCanvas } from "../helpers";

const DOC = `# Caching notes

## Retries

Retries can improve reliability when the cache holds a valid result. They must stop after 3 attempts, however short the outage.

## Limits

The cache keeps at most 500 entries per tenant. Entries expire after 30 minutes. Thanks for reading.
`;
const PLANTED: DistillerOptions = { uncitedIn: /expire after/, persistent: true };

const reviewBar = (p: Page) => p.getByRole("region", { name: "AI changes to review" });
const notes = (p: Page) => p.getByTestId("acute-notes-view");
const studyCards = (p: Page) => notes(p).locator(".acute-notes__study-grid > .acute-notes__note");
const badges = (p: Page) => notes(p).getByTestId("acute-notes-study-badges");

type Dev = {
  setNoteModel(m: string): Promise<string>;
  store: { flush(): Promise<void> };
  reconciliation(id: string): Promise<{ link: { contentSourceVersion: number; sourceUnits?: string[] } | null } | null>;
};
const setDistil = (p: Page) => p.evaluate(() => (window as unknown as { __acuteDev: Dev }).__acuteDev.setNoteModel("distil"));
const linkOf = (p: Page, id: string) =>
  p.evaluate(async (objectId) => (await (window as unknown as { __acuteDev: Dev }).__acuteDev.reconciliation(objectId))?.link ?? null, id);

async function answerLocally(page: Page): Promise<void> {
  await page.route("**/api/ai/**", async (route: Route) => {
    const path = new URL(route.request().url()).pathname;
    if (!path.endsWith("/run")) return route.fulfill({ status: 200, json: [] });
    const body = route.request().postDataJSON() as { request?: AIRequest };
    const req = { ...(body.request ?? {}), task: body.request?.task ?? "", prompt: body.request?.prompt ?? "" } as AIRequest;
    return route.fulfill({ status: 200, json: { text: distiller(PLANTED)(req).text, model: "test-model", finishReason: "stop", usage: { provider: "openai", model: "test-model" } } });
  });
}

async function connectFakeKey(page: Page) {
  const settings = await openAISettings(page);
  const row = settings.locator(".acute-ai-row").filter({ has: page.locator(".acute-ai-row__title", { hasText: /^OpenAI$/ }) });
  await row.getByRole("button", { name: "Connect key" }).click();
  const connect = page.getByRole("dialog", { name: "Connect OpenAI" });
  await connect.locator("#acute-connect-key").fill("sk-test-not-a-real-key");
  await connect.locator("#acute-connect-model").fill("test-model");
  await connect.getByRole("button", { name: "Connect", exact: true }).click();
  await expect(connect).toBeHidden();
  await settings.getByRole("button", { name: "Close" }).click();
}

const reload = async (page: Page) => {
  await page.evaluate(() => (window as unknown as { __acuteDev: Dev }).__acuteDev.store.flush());
  await page.reload();
  await waitForCanvas(page);
};

async function openStudy(page: Page, kind?: "Weak" | "Flashcards") {
  if (!(await notes(page).isVisible())) await page.getByTestId("toolbar-acute-notes").click();
  await expect(notes(page)).toBeVisible();
  await notes(page).getByRole("group", { name: "Mode" }).getByRole("button", { name: "Study" }).click();
  if (kind) await notes(page).getByRole("group", { name: "Study mode" }).getByRole("button", { name: kind }).click();
}

test.describe("Changed studied card: regenerated, history kept and marked out of date (gate 1)", () => {
  test.describe.configure({ mode: "serial" });
  let page: Page;
  let studied: { id: string; units: string[] };

  test.beforeAll(async ({ browser }) => {
    page = await browser.newPage({ viewport: { width: 1600, height: 1000 } });
    await openApp(page);
    await answerLocally(page);
    await connectFakeKey(page);
    expect(await setDistil(page)).toBe("distil");
    await page.getByRole("button", { name: "More", exact: true }).click();
    await page.getByRole("menuitem", { name: "Visualize content…" }).click();
    const visualize = page.getByRole("dialog", { name: "Visualize" });
    await visualize.getByRole("textbox").fill(DOC);
    await visualize.getByRole("button", { name: "Visualize", exact: true }).click();
    await expect(reviewBar(page)).toBeVisible({ timeout: 60_000 });
    await reviewBar(page).getByRole("button", { name: /^Accept all/ }).click();
    await expect(reviewBar(page)).toBeHidden();
  });
  test.afterAll(async () => {
    await page?.context().close();
  });

  test("1. mark the '500 entries' card Weak", async () => {
    await openStudy(page, "Flashcards");
    const card = studyCards(page).filter({ hasText: /at most 500/ }).first();
    await card.locator(".openui-flashcard__face").click();
    await card.getByRole("button", { name: "Missed it" }).click();
    await expect(card.getByTestId("acute-notes-study-badges")).toHaveText("Weak");
    const id = (await card.getAttribute("data-note-anchor"))!;
    const link = await linkOf(page, id);
    expect(link?.contentSourceVersion).toBe(1);
    expect(link?.sourceUnits?.length).toBeGreaterThan(0);
    studied = { id, units: link!.sourceUnits! };
    await expect(badges(page)).toHaveCount(1); // only the studied card carries study badges
  });

  test("2–4. change its passage, Update from new content: it regenerates with no conflict and no unrelated removal", async () => {
    await reload(page);
    await expect(notes(page)).toBeHidden();
    expect(await setDistil(page)).toBe("distil"); // Fix A applies under distil, which resets on reload
    const surface = await openAskAI(page, studied.id);
    await (await action(surface, "Update from new content")).click();
    const update = page.getByRole("dialog", { name: "Update from new content" });
    await update.getByRole("textbox").fill(DOC.replace("500 entries", "600 entries"));
    await update.getByRole("button", { name: "Update", exact: true }).click();
    await expect(reviewBar(page)).toBeVisible({ timeout: 60_000 });
    const summary = (await reviewBar(page).textContent()) ?? "";
    expect(summary, "no change needs the user's input (no unrelated-card conflict)").not.toMatch(/needs your input|Conflict/);
    expect(summary, "no card is removed").not.toMatch(/removed/);
    await reviewBar(page).getByRole("button", { name: /^Accept all/ }).click();
    await expect(reviewBar(page)).toBeHidden();
  });

  const checkAfterUpdate = async () => {
    await openStudy(page, "Flashcards");
    const card = studyCards(page).filter({ hasText: /at most 600/ });
    await expect(card).toHaveCount(1);
    await expect(studyCards(page).filter({ hasText: /at most 500/ })).toHaveCount(0);
    const id = (await card.getAttribute("data-note-anchor"))!;
    const link = await linkOf(page, id);
    // The regenerated card cites the changed passage at version 2 (same passage id: the lineage carries it).
    expect(link?.contentSourceVersion, `card ${id} (was ${studied.id})`).toBe(2);
    expect([...(link?.sourceUnits ?? [])].sort(), "cites the same (changed) passage").toEqual([...studied.units].sort());
    // History kept on it, out of date: stale answers don't count, so it isn't Weak any more.
    await expect(card.getByTestId("acute-notes-study-badges")).toHaveText("Source changed since you studied this");
    // No other card picks up that history.
    await expect(badges(page)).toHaveCount(1);
    await notes(page).getByRole("group", { name: "Study mode" }).getByRole("button", { name: "Weak" }).click();
    await expect(notes(page).getByTestId("acute-notes-weak")).toContainText("Nothing weak yet");
  };

  test("5. the regenerated card cites the changed passage, keeps the history marked out of date, and no other card has it", async () => {
    await reload(page);
    await checkAfterUpdate();
  });

  test("6. still so after another reload", async () => {
    await reload(page);
    await checkAfterUpdate();
  });
});
